module.exports = { TEMPLATE: "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>What Is My IP Address? \u2014 plus curl dorh.fyi/ip for scripts</title>\n<meta name=\"description\" content=\"See your public IP address, approximate location and timezone. Get it from the command line with curl https://dorh.fyi/ip (plain text) or /ip.json. No logging, no ads, no tracking.\">\n<link rel=\"canonical\" href=\"https://dorh.fyi/my-ip\">\n<meta property=\"og:type\" content=\"website\">\n<meta property=\"og:title\" content=\"What Is My IP Address? \u2014 plus curl dorh.fyi/ip for scripts\">\n<meta property=\"og:description\" content=\"See your public IP address, approximate location and timezone. Get it from the command line with curl https://dorh.fyi/ip (plain text) or /ip.json. No logging, no ads, no tracking.\">\n<meta property=\"og:url\" content=\"https://dorh.fyi/my-ip\">\n<meta name=\"twitter:card\" content=\"summary\">\n<meta name=\"theme-color\" content=\"#0f1115\">\n<link rel=\"icon\" href=\"/favicon.svg\" type=\"image/svg+xml\">\n<link rel=\"stylesheet\" href=\"/assets/style.css\">\n<script type=\"application/ld+json\">{\"@context\": \"https://schema.org\", \"@type\": \"WebApplication\", \"name\": \"What Is My IP\", \"url\": \"https://dorh.fyi/my-ip\", \"applicationCategory\": \"DeveloperApplication\", \"operatingSystem\": \"Any (browser)\", \"isAccessibleForFree\": true, \"offers\": {\"@type\": \"Offer\", \"price\": \"0\", \"priceCurrency\": \"USD\"}, \"description\": \"See your public IP address, approximate location and timezone. Get it from the command line with curl https://dorh.fyi/ip (plain text) or /ip.json. No logging, no ads, no tracking.\"}</script>\n<script type=\"application/ld+json\">{\"@context\": \"https://schema.org\", \"@type\": \"FAQPage\", \"mainEntity\": [{\"@type\": \"Question\", \"name\": \"How do I find my public IP from the command line?\", \"acceptedAnswer\": {\"@type\": \"Answer\", \"text\": \"Run curl https://dorh.fyi/ip. It returns just the address and a newline, so it works directly in shell scripts. Use /ip.json if you also want the IP version, country and timezone.\"}}, {\"@type\": \"Question\", \"name\": \"Is my IP address logged?\", \"acceptedAnswer\": {\"@type\": \"Answer\", \"text\": \"No. The response is built per request from the connection data and never stored or cached. The hosting provider may keep standard short-lived access logs for security, like any website.\"}}, {\"@type\": \"Question\", \"name\": \"Why is my IP different from what ipconfig or ip addr shows?\", \"acceptedAnswer\": {\"@type\": \"Answer\", \"text\": \"Your device usually has a private address (10.x, 172.16\u201331.x, 192.168.x) behind NAT. Websites only ever see the public address of your router, ISP or VPN, which is what this page shows.\"}}, {\"@type\": \"Question\", \"name\": \"Why does the location look wrong?\", \"acceptedAnswer\": {\"@type\": \"Answer\", \"text\": \"IP geolocation databases map address blocks to the ISP's registered or routing location, not your physical position. Mobile networks and CGNAT often show a city far away, or just the country.\"}}]}</script>\n<script src=\"/assets/common.js\" defer></script>\n</head>\n<body>\n<header class=\"site\"><div class=\"wrap\">\n<a class=\"logo\" href=\"/\">dorh<span>.fyi</span></a>\n<nav class=\"top\"><a href=\"/#tools\">Tools</a><a href=\"/privacy\">Privacy</a><a href=\"/about\">About</a></nav>\n</div></header>\n<main><div class=\"wrap\">\n\n<span class=\"badge\">\u25cf Nothing is logged or stored. The page is generated per request and never cached.</span>\n<h1>What is my IP address?</h1>\n<div class=\"card\">\n  <div class=\"ipbig mono\" id=\"myip\">__IP__</div>\n  <div class=\"row\"><button class=\"secondary\" data-copy=\"#myip\">Copy</button></div>\n  <div class=\"kv u-mt12\">\n    <div>Version</div><div>__VER__</div>\n    <div>Approx. location</div><div>__LOC__</div>\n    <div>Timezone</div><div>__TZ__</div>\n    <div>User agent</div><div>__UA__</div>\n  </div>\n</div>\n\n<h2>From the command line</h2>\n<pre class=\"out\">curl https://dorh.fyi/ip          # plain text, just the IP\ncurl https://dorh.fyi/ip.json     # {\"ip\":\"\u2026\",\"version\":4,\"country\":\"\u2026\",\u2026}\n\n# PowerShell\n(Invoke-RestMethod https://dorh.fyi/ip).Trim()\n\n# in a script\nMYIP=$(curl -fsS https://dorh.fyi/ip)</pre>\n<p class=\"u-note\">Use <code class=\"mono\">https://</code> (or <code class=\"mono\">curl -L</code>). Plain HTTP gets redirected to HTTPS, and curl doesn't follow redirects by default.</p>\n\n<section class=\"prose\">\n<h2>About this result</h2>\n<p>This is the public IPv4 address that websites see when you connect, usually your router's or your ISP's (CGNAT) address, not the private address of your device. If you're on a VPN, a proxy or iCloud Private Relay, you'll see their exit address instead. The location comes from IP geolocation and is often only accurate to the city or region.</p>\n<p>This endpoint is IPv4-only, so it shows your IPv4 address even if you also have IPv6.</p>\n\n<h2>FAQ</h2>\n<h3 class=\"q\">How do I find my public IP from the command line?</h3>\n<p>Run curl https://dorh.fyi/ip. It returns just the address and a newline, so it works directly in shell scripts. Use /ip.json if you also want the IP version, country and timezone.</p>\n<h3 class=\"q\">Is my IP address logged?</h3>\n<p>No. The response is built per request from the connection data and never stored or cached. The hosting provider may keep standard short-lived access logs for security, like any website.</p>\n<h3 class=\"q\">Why is my IP different from what ipconfig or ip addr shows?</h3>\n<p>Your device usually has a private address (10.x, 172.16\u201331.x, 192.168.x) behind NAT. Websites only ever see the public address of your router, ISP or VPN, which is what this page shows.</p>\n<h3 class=\"q\">Why does the location look wrong?</h3>\n<p>IP geolocation databases map address blocks to the ISP's registered or routing location, not your physical position. Mobile networks and CGNAT often show a city far away, or just the country.</p>\n</section>\n\n</div></main>\n<footer class=\"site\"><div class=\"wrap\">\nEvery tool runs locally in your browser. Nothing you paste or drop is uploaded. &nbsp;\u00b7&nbsp;\n<a href=\"/privacy\">Privacy</a> \u00b7 <a href=\"/about\">About</a> \u00b7 \u00a9 2026 dorh.fyi\n</div></footer>\n</body>\n</html>\n" };
